int fiboA(int n)
{
    if(n==0)
        return 1;
    if(n==1)
        return 1;
    else
    {
        return fiboA(n-1)+fiboA(n-2);
    }
}
int fiboB(int n)
{
    if( (n==0) || (n==1) ){
        fiboB[n]=n;
        return n;
    }
    else{
        if(fiboB[n] == 0){
            fiboB[n]=FiboB(n-1)+FiboB(n-2);
        }
        return fiboB[n];
    }
}
